#!/usr/bin/env python3
"""What a reader sees must not carry workshop talk.   python3 tools/plainwords_test.py
Run it after changing tools/plainwords.py. Place text is written by research sessions, and some of it says "in this session" or
names a tool; the build rewrites those words (tools/build_sites.py) so the sources stay as they were written."""
import sys,os,importlib
HERE=os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0,HERE)
fails=[]
def ok(name,cond,extra=''):
    print(('ok   ' if cond else 'FAIL ')+name+(('  ['+str(extra)[:170]+']') if extra!='' else ''))
    if not cond: fails.append(name)
try: pw=importlib.import_module('plainwords')
except Exception as e: print('FAIL plainwords.py can be imported  [%s]'%str(e)[:100]); print('1 FAILED'); sys.exit(1)
T=pw.text; N=pw.pin_note
ok('"would not open in this session" becomes "when this was written"',T('orda.org would not open in this session: hours not checked.')=='orda.org would not open when this was written: hours not checked.',T('orda.org would not open in this session: hours not checked.'))
ok('"refused this session" too',T('The DCR page refused this session, so hours and fees not checked.')=='The DCR page refused to open when this was written, so hours and fees not checked.',T('The DCR page refused this session, so hours and fees not checked.'))
ok('"answered 403 in this session" too',T('Its pages answered HTTP 403 in this session, so hours were not checked.')=='Its pages answered HTTP 403 when this was written, so hours were not checked.')
ok('a page "read in this session" is a page read',T('Hours were not on any page read in this session: hours not checked.')=='Hours were not on any page read: hours not checked.' and T('(not seen in this session)')=='(not seen)',T('Hours were not on any page read in this session: hours not checked.'))
ok('a photograph "opened in this session" is just a photograph',T('A March 2010 Wikimedia Commons photograph opened in this session shows grey stone walls.')=='A March 2010 Wikimedia Commons photograph shows grey stone walls.',T('A March 2010 Wikimedia Commons photograph opened in this session shows grey stone walls.'))
ok('"would not open from here" becomes "when this was written"; an ordinary "from here" is left alone',T("the town's news pages would not open from here.")=="the town's news pages would not open when this was written." and T('The first sail ferry left from here in 1785.')=='The first sail ferry left from here in 1785.',T("the town's news pages would not open from here."))
ok('"the pin check" is "the aerial"',T('not checked beyond what the pin check showed.')=='not checked beyond what the aerial showed.')
ok('text with none of these words is returned as it was, and nothing is not text',T('Park at the trailhead. Open dawn to dusk.')=='Park at the trailhead. Open dawn to dusk.' and T('')=='' and T(None) is None)
ok('a tool named in brackets is taken out of a pin note',N('OpenStreetMap bridge (tools/nom.py), matching the guide waypoint.')=='OpenStreetMap bridge, matching the guide waypoint.' and N('OpenStreetMap feature (tools/nom.py / osmnear.py).')=='OpenStreetMap feature.',N('OpenStreetMap feature (tools/nom.py / osmnear.py).'))
ok('"moved with tools/pix.py" is "moved"',N('Register point moved 21 m east with tools/pix.py onto the long barracks.')=='Register point moved 21 m east onto the long barracks.' and N('Moved with tools/pix.py about 30 m south.')=='Moved about 30 m south.',N('Moved with tools/pix.py about 30 m south.'))
ok('"from tools/parking.py" is "from OpenStreetMap", said once',N('Wikipedia coordinate; parking from tools/parking.py.')=='Wikipedia coordinate; parking from OpenStreetMap.' and N('the OpenStreetMap lot from tools/parking.py, a gravel loop.')=='the OpenStreetMap lot, a gravel loop.',N('the OpenStreetMap lot from tools/parking.py, a gravel loop.'))
ok('"the pin-check aerial" is "the aerial", and no tool name is left in any form',N('seen on the pin-check aerial (tools/pix.py).')=='seen on the aerial.' and 'tools/' not in N('read off a wide aerial with tools/pix.py; checked by tools/look.py and tools/whatever.py'),N('read off a wide aerial with tools/pix.py; checked by tools/look.py and tools/whatever.py'))
ok('a pin note gets the text rules as well',N('Its page would not open in this session.')=='Its page would not open when this was written.')
ok('a session of a court or a legislature is not workshop talk',T('The charter passed in the session of 1849.')=='The charter passed in the session of 1849.' and T('The court sat here in the session after the fire.')=='The court sat here in the session after the fire.')
ok('"read this session", "by this session" and "this session takes" are put plainly',T('not found on a page read this session.')=='not found on a page read.' and T('Interior not checked by this session.')=='Interior not checked.' and N('the small building, which this session takes to be the school.')=='the small building, which is taken to be the school.' and T("(outdoornebraska.gov refuses this session's tools)")=='(outdoornebraska.gov refuses to open)',[T('not found on a page read this session.'),T('Interior not checked by this session.'),N('the small building, which this session takes to be the school.'),T("(outdoornebraska.gov refuses this session's tools)")])
ok('a tool named without its folder goes too: "moved with pix.py", "with look.py and pix.py", "(look.py, pix.py)"',N('The Register point fell on a field; moved with pix.py onto a track.')=='The Register point fell on a field; moved onto a track.' and N('Moved with look.py and pix.py to the cross-plan building.')=='Moved to the cross-plan building.' and N('seen on the aerial (look.py, pix.py). Not confirmed.')=='seen on the aerial. Not confirmed.' and N('moved 124 m (pix.py on a look.py view) onto Lordville Road')=='moved 124 m onto Lordville Road' and N('moved with pix.py on a closer look.py view onto the large building')=='moved onto the large building',[N('Moved with look.py and pix.py to the cross-plan building.'),N('moved 124 m (pix.py on a look.py view) onto Lordville Road'),N('moved with pix.py on a closer look.py view onto the large building')])
ok('what a tool found is credited to the map it reads',N('Parking from parking.py.')=='Parking from OpenStreetMap.' and N('The lot parking.py offered looked like grass.')=='The lot OpenStreetMap offered looked like grass.' and N("OpenStreetMap's museum point, found with nom.py.")=="OpenStreetMap's museum point." and N('OpenStreetMap "Silver Bay Inn" from nom.py.')=='OpenStreetMap "Silver Bay Inn".' and N('the address nom.py gives for the church.')=='the address OpenStreetMap gives for the church.' and N('OpenStreetMap building (osmnear.py buildings), not the new church.')=='OpenStreetMap building, not the new church.',[N('Parking from parking.py.'),N("OpenStreetMap's museum point, found with nom.py."),N('OpenStreetMap "Silver Bay Inn" from nom.py.'),N('OpenStreetMap building (osmnear.py buildings), not the new church.')])
ok('the Atlas\'s own check is called that, the aerial viewer is "the aerial", and no file name is left whatever it is',N('because check.py then refused the house')=="because the Atlas's own check then refused the house" and N('the aerial (look.py, 250 m) shows a few buildings')=='the aerial shows a few buildings' and '.py' not in N('checked by whatever.py and pincheck.py, then other_tool.py move') and N('The pin check shows the lock chambers.')=='The aerial shows the lock chambers.' and N('with the churchyard round it (pin check, November 18, 2026).')=='with the churchyard round it (checked on the aerial, November 18, 2026).',[N('because check.py then refused the house'),N('the aerial (look.py, 250 m) shows a few buildings'),N('checked by whatever.py and pincheck.py, then other_tool.py move')])
ok('"prec is site" is said in words',N('could not be told, so prec is site.')=='could not be told, so the pin marks the site.' and N('not picked out yet; prec area.')=='not picked out yet; the pin marks the area.' and N('so prec stays site.')=='so the pin still marks the site.' and N('on the roof: prec exact.')=='on the roof: the pin is exact.',[N('could not be told, so prec is site.'),N('so prec stays site.')])
ok('written as the data field is, "prec=area" or "prec=\'site\'", it is said in words too',N("could not be picked out, so prec=area.")=='could not be picked out, so the pin marks the area.' and N("so prec='site'. HMdb's marker")=="so the pin marks the site. HMdb's marker",[N("so prec='site'. HMdb's marker")])
S1=pw.site({'id':'x','story':'Built 1850.','accn':'The lot 100 m north (parking.py) is private; its page would not open in this session.','pn':'Moved with pix.py onto the roof.'})
ok('every reader-facing field of a place goes through both sets of rules, and other fields are left alone',S1['accn']=='The lot 100 m north is private; its page would not open when this was written.' and S1['pn']=='Moved onto the roof.' and S1['story']=='Built 1850.' and S1['id']=='x',S1)
print(f'{len(fails)} FAILED' if fails else 'plain words test: all checks passed'); sys.exit(1 if fails else 0)
